// k6 smoke test: a few virtual users for a short time. Proves the script works and the system answers fast
// under minimal load. Run it before every load test and after deploys. Generated by `eos scaffold load-k6`.
// Run: k6 run -e BASE_URL=https://staging.example.com load/smoke.js
// Background: .eos/packs/ref/testing/performance-k6.md
import http from "k6/http";
import { check, sleep } from "k6";

const BASE_URL = __ENV.BASE_URL || "http://127.0.0.1:8000";

export const options = {
  vus: 2,
  duration: "30s",
  thresholds: {
    // A failed threshold makes k6 exit non-zero, so CI fails. Checks alone never fail a run.
    http_req_failed: ["rate<0.01"], // under 1% errors
    http_req_duration: ["p(95)<500"], // 95% of requests under 500 ms (set from your SLO)
    checks: ["rate>0.99"],
  },
};

export default function () {
  const res = http.get(`${BASE_URL}/`, { tags: { name: "home" } });
  check(res, { "status is 2xx/3xx": (r) => r.status >= 200 && r.status < 400 });
  sleep(1);
}
